SUBROUTINE SETUP_TRANS0(KOUT, KERR, KPRINTLEV, KMAX_RESOL, KPROMATR, KPRGPNS, KPRGPEW, KPRTRW, &
  &                     KCOMBFLEN, LDMPOFF, LDSYNC_TRANS, KTRANS_SYNC_LEVEL, LDEQ_REGIONS, &
  &                     K_REGIONS_NS, K_REGIONS_EW, K_REGIONS, PRAD, LDALLOPERM, KOPT_MEMORY_TR)

USE PARKIND1, ONLY: JPIM, JPRD
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_DOUBLE

IMPLICIT NONE

INTERFACE
SUBROUTINE SETUP_TRANS0_CPP_BINDING(KOUT, KERR, KPRINTLEV, KMAX_RESOL, KPROMATR, KPRGPNS, KPRGPEW, &
  &                                 KPRTRW, KDMPOFF, KDSYNC_TRANS, KTRANS_SYNC_LEVEL, &
  &                                 KDEQ_REGIONS, PRAD, KDALLOPERM, KOPT_MEMORY_TR, K_REGIONS_NS, &
  &                                 K_REGIONS_EW, K_REGIONS) BIND(C, NAME="setup_trans0")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_DOUBLE
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KOUT
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KERR
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KPRINTLEV
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KMAX_RESOL
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KPROMATR
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KPRGPNS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KPRGPEW
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KPRTRW
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KMPOFF
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KSYNC_TRANS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KTRANS_SYNC_LEVEL
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KEQ_REGIONS
  REAL(KIND=C_DOUBLE), VALUE,    INTENT(IN)    :: PRAD
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KALLOPERM
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KOPT_MEMORY_TR
  INTEGER(KIND=C_INT),           INTENT(INOUT) :: K_REGIONS_NS
  INTEGER(KIND=C_INT),           INTENT(INOUT) :: K_REGIONS_EW
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(INOUT) :: K_REGIONS(:)
END SUBROUTINE SETUP_TRANS0_CPP_BINDING
END INTERFACE

INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KOUT
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KERR
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPRINTLEV
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KMAX_RESOL
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPROMATR
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPRGPNS
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPRGPEW
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPRTRW
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KCOMBFLEN
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDMPOFF
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDSYNC_TRANS
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KTRANS_SYNC_LEVEL
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDEQ_REGIONS
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: K_REGIONS_NS
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: K_REGIONS_EW
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: K_REGIONS(:)
REAL(KIND=JPRD),    OPTIONAL, INTENT(IN)  :: PRAD
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDALLOPERM
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KOPT_MEMORY_TR

INTEGER(KIND=C_INT) :: IOUT, IERR, IPRINTLEV, IMAX_RESOL, IPROMATR, IPRGPNS, IPRGPEW, IPRTRW
INTEGER(KIND=C_INT) :: IMPOFF, ISYNC_TRANS, ITRANS_SYNC_LEVEL, IEQ_REGIONS, IALLOPERM
INTEGER(KIND=C_INT) :: IOPT_MEMORY_TR, I_REGIONS_NS, I_REGIONS_EW
REAL(KIND=C_DOUBLE) :: ZRAD

INTEGER(KIND=JPIM) :: IOUT_HERE

! OPTIONAL, INTENT(IN) arguments
IF (PRESENT(KOUT)) THEN
  IOUT = KOUT
ELSE
  IOUT = -1
ENDIF
IF (PRESENT(KERR)) THEN
  IERR = KERR
ELSE
  IERR = -1
ENDIF
IF (PRESENT(KPRINTLEV)) THEN
  IPRINTLEV = KPRINTLEV
ELSE
  IPRINTLEV = -1
ENDIF
IF (PRESENT(KMAX_RESOL)) THEN
  IMAX_RESOL = KMAX_RESOL
ELSE
  IMAX_RESOL = -1
ENDIF
IF (PRESENT(KPROMATR)) THEN
  IPROMATR = KPROMATR
ELSE
  IPROMATR = -1
ENDIF
IF (PRESENT(KPRGPNS)) THEN
  IPRGPNS = KPRGPNS
ELSE
  IPRGPNS = -1
ENDIF
IF (PRESENT(KPRGPEW)) THEN
  IPRGPEW = KPRGPEW
ELSE
  IPRGPEW = -1
ENDIF
IF (PRESENT(KPRTRW)) THEN
  IPRTRW = KPRTRW
ELSE
  IPRTRW = -1
ENDIF
! This is deprecated so we won't bother to include it in the C++ layer
! 
IF (PRESENT(KCOMBFLEN)) THEN
  IF (PRESENT(KOUT)) THEN
    IOUT_HERE = KOUT
  ELSE
    IOUT_HERE = 6
  ENDIF
  WRITE(IOUT_HERE,'(A)')
  WRITE(IOUT_HERE,'(A)') '*** WARNING ***'
  WRITE(IOUT_HERE,'(A)') 'KCOMBFLEN argument passed to SETUP_TRANS0 is deprecated'
  WRITE(IOUT_HERE,'(A)')
ENDIF
IF (PRESENT(LMPOFF)) THEN
  IMPOFF = MERGE(1, 0, LDMPOFF)
ELSE
  IMPOFF = -1
ENDIF
IF (PRESENT(LDSYNC_TRANS)) THEN
  ISYNC_TRANS = MERGE(1, 0, LDSYNC_TRANS)
ELSE
  ISYNC_TRANS = -1
ENDIF
IF (PRESENT(KTRANS_SYNC_LEVEL)) THEN
  ITRANS_SYNC_LEVEL = KTRANS_SYNC_LEVEL
ELSE
  ITRANS_SYNC_LEVEL = -1
ENDIF
IF (PRESENT(LDEQ_REGIONS)) THEN
  IEQ_REGIONS = MERGE(1, 0, LDEQ_REGIONS)
ELSE
  IEQ_REGIONS = -1
ENDIF
IF (PRESENT(PRAD)) THEN
  ZRAD = PRAD
ELSE
  ZRAD = -1.0_JPRD
ENDIF
IF (PRESENT(LDALLOPERM)) THEN
  IALLOPERM = MERGE(1, 0, LDALLOPERM)
ELSE
  IALLOPERM = -1
ENDIF
IF (PRESENT(KOPT_MEMORY_TR)) THEN
  IOPT_MEMORY_TR = KOPT_MEMORY_TR
ELSE
  IOPT_MEMORY_TR = -1
ENDIF

! OPTIONAL, INTENT(INOUT) arguments
! These correspond to INTENT(OUT) arguments of SETUP_TRANS0 and so do *not* have defined values yet
! This logic is purely to indicate whether they are present or not within the C++ layer
IF (PRESENT(K_REGIONS_NS)) THEN
  I_REGIONS_NS = 0
ELSE
  I_REGIONS_NS = -1
ENDIF
IF (PRESENT(K_REGIONS_EW)) THEN
  I_REGIONS_EW = 0
ELSE
  I_REGIONS_EW = -1
ENDIF

CALL SETUP_TRANS0_CPP_BINDING(IOUT, IERR, IPRINTLEV, IMAX_RESOL, IPROMATR, IPRGPNS, IPRGPEW, &
  &                           IPRTRW, IMPOFF, ISYNC_TRANS, ITRANS_SYNC_LEVEL, IEQ_REGIONS, ZRAD, &
  &                           IALLOPERM, IOPT_MEMORY_TR, I_REGIONS_NS, I_REGIONS_EW, &
  &                           K_REGIONS=K_REGIONS)

! OPTIONAL, INTENT(INOUT) arguments
IF (PRESENT(K_REGIONS_NS)) K_REGIONS_NS = I_REGIONS_NS
IF (PRESENT(K_REGIONS_EW)) K_REGIONS_EW = I_REGIONS_EW

END SUBROUTINE SETUP_TRANS0
